# 分布式事务补充方案
> **定位**：生产中最常用的方案，面试高频追问
## 一、本地消息表 + MQ（生产最常用）
### 1.1 核心思想
**将"业务操作"和"消息发送"绑定在同一个本地事务中**，通过定时任务保证消息一定发出去。
```
┌──────────────────────────────────────────────────────────┐
│                    订单服务                                │
│                                                          │
│  BEGIN TRANSACTION                                       │
│    ① INSERT INTO orders (...)                            │
│    ② INSERT INTO outbox_messages (event_type, payload)   │  ← 同一个事务
│  COMMIT                                                  │
│                                                          │
│  ③ 定时任务扫描 outbox_messages 表                         │
│     → 发送到 MQ → 发送成功则标记为已发送                     │
└───────────────────────┬──────────────────────────────────┘
│ MQ
┌───────────────────────▼──────────────────────────────────┐
│                    库存服务                                │
│  ④ 消费消息 → 扣减库存 → 幂等处理                           │
└──────────────────────────────────────────────────────────┘
```
### 1.2 代码实现
```java
// 1. 本地消息表
CREATE TABLE outbox_messages (
id BIGINT PRIMARY KEY AUTO_INCREMENT,
event_type VARCHAR(64) NOT NULL,      -- 事件类型
payload TEXT NOT NULL,                 -- 消息体（JSON）
status TINYINT DEFAULT 0,             -- 0:待发送 1:已发送 2:发送失败
retry_count INT DEFAULT 0,            -- 重试次数
created_at DATETIME DEFAULT NOW(),
sent_at DATETIME
);
// 2. 业务操作 + 写消息表（同一个事务）
@Service
public class OrderService {
@Transactional
public void createOrder(CreateOrderCmd cmd) {
// 业务操作
Order order = new Order(cmd);
orderRepo.save(order);
// 写本地消息表（同一个事务）
OutboxMessage msg = new OutboxMessage();
msg.setEventType("ORDER_CREATED");
msg.setPayload(JSON.toJSONString(new OrderCreatedEvent(order.getId())));
outboxRepo.save(msg);
}
}
// 3. 定时任务扫描消息表并发送
@Component
public class OutboxPublisher {
@Scheduled(fixedDelay = 1000)  // 每秒扫描一次
public void publishPendingMessages() {
List<OutboxMessage> messages = outboxRepo.findByStatus(0);
for (OutboxMessage msg : messages) {
try {
rabbitTemplate.convertAndSend("order.exchange", "order.created", msg.getPayload());
msg.setStatus(1);  // 已发送
msg.setSentAt(LocalDateTime.now());
outboxRepo.save(msg);
} catch (Exception e) {
msg.setRetryCount(msg.getRetryCount() + 1);
if (msg.getRetryCount() >= 5) {
msg.setStatus(2);  // 标记失败，人工介入
}
outboxRepo.save(msg);
}
}
}
}
// 4. 消费端：幂等处理
@Component
public class InventoryConsumer {
@RabbitListener(queues = "inventory.queue")
public void handleOrderCreated(String payload) {
OrderCreatedEvent event = JSON.parseObject(payload, OrderCreatedEvent.class);
// 幂等检查：用事件ID去重
if (processedEventRepo.existsById(event.getEventId())) {
log.info("事件已处理，跳过: {}", event.getEventId());
return;
}
// 执行业务
inventoryService.deduct(event.getOrderId(), event.getItems());
// 记录已处理
processedEventRepo.save(new ProcessedEvent(event.getEventId()));
}
}
```
